-- ============================================================
--  STEP 1: Create the Database
--  Run this block first, then switch to SalesAssessment
-- ============================================================
IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = 'SalesAssessment')
    CREATE DATABASE SalesAssessment;
GO

USE SalesAssessment;
GO

-- ============================================================
--  STEP 2: Create Tables
-- ============================================================

-- Drop tables if they already exist (safe re-run)
IF OBJECT_ID('dbo.SalesTransactions', 'U') IS NOT NULL DROP TABLE dbo.SalesTransactions;
IF OBJECT_ID('dbo.Products', 'U') IS NOT NULL DROP TABLE dbo.Products;
IF OBJECT_ID('dbo.Salesperson', 'U') IS NOT NULL DROP TABLE dbo.Salesperson;
GO

CREATE TABLE dbo.Salesperson (
    SalespersonID   VARCHAR(10)     NOT NULL PRIMARY KEY,
    SalespersonName NVARCHAR(100)   NOT NULL,
    Region          VARCHAR(10)     NOT NULL,
    SalesTarget     BIGINT          NOT NULL
);
GO

CREATE TABLE dbo.Products (
    ProductID   INT             NOT NULL PRIMARY KEY,
    ProductName NVARCHAR(100)   NOT NULL,
    Category    VARCHAR(20)     NOT NULL,
    Price       DECIMAL(10,2)   NOT NULL
);
GO

CREATE TABLE dbo.SalesTransactions (
    RowID           INT IDENTITY(1,1) PRIMARY KEY,
    TransactionID   INT             NOT NULL,
    SaleDate        DATE            NOT NULL,
    ProductID       INT             NOT NULL,
    ProductCategory VARCHAR(20)     NOT NULL,
    Region          VARCHAR(10)     NOT NULL,
    SalesChannel    VARCHAR(10)     NOT NULL,
    SalespersonID   VARCHAR(10)     NOT NULL,
    QuantitySold    INT             NOT NULL,
    DiscountPct     DECIMAL(5,2)    NOT NULL,
    CONSTRAINT FK_Sales_Product     FOREIGN KEY (ProductID)     REFERENCES dbo.Products(ProductID),
    CONSTRAINT FK_Sales_Salesperson FOREIGN KEY (SalespersonID) REFERENCES dbo.Salesperson(SalespersonID)
);
GO

