-- ============================================================
--  STEP 6: Verify the Data
-- ============================================================
SELECT 'Salesperson' AS TableName, COUNT(*) AS Row_Count FROM dbo.Salesperson
UNION ALL
SELECT 'Products',       COUNT(*) FROM dbo.Products
UNION ALL
SELECT 'SalesTransactions', COUNT(*) FROM dbo.SalesTransactions;
GO

-- Check a sample of sales with joined names and prices
SELECT TOP 10
    st.TransactionID,
    st.SaleDate,
    p.ProductName,
    p.Price,
    st.ProductCategory,
    st.Region,
    st.SalesChannel,
    sp.SalespersonName,
    st.QuantitySold,
    st.DiscountPct,
    (st.QuantitySold * p.Price) AS GrossSales,
    (st.QuantitySold * p.Price * st.DiscountPct / 100) AS DiscountAmount,
    (st.QuantitySold * p.Price * (1 - st.DiscountPct/100)) AS NetSales
FROM dbo.SalesTransactions st
JOIN dbo.Products p    ON st.ProductID = p.ProductID
JOIN dbo.Salesperson sp ON st.SalespersonID = sp.SalespersonID;
GO